head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setUseFilterList]<br/>GridView 컴포넌트의 useFilterList 속성을 설정합니다.",
    "validation" : [
        "filterList(필수) 파라미터로 useFilterList 속성값을 true/false 로 설정할 수 있어야 합니다.",
        "filterList(필수) 파라미터를 true 로 설정 시, useFilter=true 인 Header Column 에 CustomFilter 와 FilterList 기능을 활성화합니다.",
        "filterList(필수) 파라미터를 false 로 설정 시, useFilter=true 인 Header Column 에 CustomFilter 기능만 활성화합니다.",
        "FilterList 는 해당 Column 의 데이터를 동적으로 목록화하여 제공하는 기능입니다.",
        "headerFilter=true 이면 useFilterList 속성은 무시됩니다.",
        "useFilter=false 인 Header Column 에는 useFilterList 속성이 적용되지 않습니다.",
        "useFilterList 속성은 GridView 전체에 일괄 적용되며 Column 별로 설정할 수 없습니다.",
        "FilterList 기능의 데이터 목록은 동적으로 변경되며 다른 Column 에 의해 필터가 적용된 경우 실제 화면에 표시되는 데이터만 목록에 표시됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 렌더 전제(con) : headerFilter (gdl_boolean getText → '' / 'true' / 'false')
    //  - useFilterList 는 렌더 시 절대 설정하지 않음(동적 setUseFilterList 로만 켬).
    //  - sortable/showSortableImage 는 설정하지 않음(비-sortable 그리드) → useFilter=true Header 에 필터 아이콘 상시 표시되어 클릭 가능.
    let vHeaderFilter = con_headerFilter.getText();

    let properties = {};
    // headerFilter=true 는 P_useFilterList_3 참고: defaultShowHeaderFilter=true 로 HeaderFilter 필터 행이 화면에 보이도록 함
    //  (그래야 useFilterList 무시 시 HeaderFilter 가 대신 동작함을 눈으로 확인 가능)
    if (vHeaderFilter === 'true') { properties.headerFilter = true; properties.defaultShowHeaderFilter = true; }
    else if (vHeaderFilter === 'false') { properties.headerFilter = false; }

    let lblDesc = '[전제] col1~col3 Header = useFilter=true (필터 아이콘 有) / col4 = useFilter=false (미적용) / RowNum·RowStatus Header 는 필터 아이콘 없음'
        + '\n headerFilter=' + (vHeaderFilter === '' ? '(미설정=false)' : vHeaderFilter)
        + '\n[절차] par_filterList 선택 후 (setUseFilterList). useFilter 컬럼 필터 아이콘 클릭해 팝업 연 뒤 (필터 팝업 유형 확인).'
        + '\n[확인] 팝업 유형(true=FilterList / false=CustomFilter) 과 options.useFilterList. headerFilter=true 면 HeaderFilter 필터 행이 표시되고 setUseFilterList(FilterList)는 무시됨.';

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="' + lblDesc + '"', '', 'label1');

    // dataList 생성 (4행, col1~col4) — P_useFilterList 와 동일 데이터
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    let cList = $c.gcm.createCList(properties);
    let grp_comp = $c.gcm.getTestGroup();
    let ns = $c.gcm.getNameSpace();

    // useFilter="true" Header Column(col1~col3) + useFilter 미설정(false) Column(col4) 을 인라인 구성한 gridView 동적 생성
    let s = '';
    s += '<w2:gridView ' + ns + ' ' + cList + ' rowNumVisible="true" rowStatusVisible="true" rowNumHeaderValue="No." rowStatusHeaderValue="St." checkAllType="false" id="" dataList="data:dlt_bind" style="width:560px;height:300px;">';
    s += '<w2:caption style="" id="caption1" value="setUseFilterList 테스트 그리드"></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="row1">';
    s += '<w2:column width="130" style="" inputType="text" id="column1" value="col1" useFilter="true"></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="column2" value="col2" useFilter="true"></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="column3" value="col3" useFilter="true"></w2:column>';
    s += '<w2:column width="*" style="" inputType="text" id="column4" value="col4"></w2:column>';
    s += '</w2:row>';
    // headerFilter=true 일 때만 HeaderFilter 필터 행(filterColumn) 추가 (P_useFilterList_3 참고). headerFilter=false 면 순수 useFilter/FilterList 그리드로 동작.
    if (vHeaderFilter === 'true') {
        s += '<w2:row style="" id="rowFilter">';
        s += '<w2:filterColumn width="130" style="" id="fcol1" value=""></w2:filterColumn>';
        s += '<w2:filterColumn width="130" style="" id="fcol2" value=""></w2:filterColumn>';
        s += '<w2:filterColumn width="130" style="" id="fcol3" value=""></w2:filterColumn>';
        s += '<w2:filterColumn width="*" style="" id="fcol4" value=""></w2:filterColumn>';
        s += '</w2:row>';
    }
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="row2">';
    s += '<w2:column width="130" style="" inputType="text" id="col1" value=""></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="col2" value=""></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="col3" value=""></w2:column>';
    s += '<w2:column width="*" style="" inputType="text" id="col4" value=""></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);
}



// [실행] setUseFilterList : filterList 값을 useFilterList 속성으로 설정.
//  headerFilter=true 면 무시(옵션 미변경).
scwin.btn_setUseFilterList_onclick = function () {
    // gdl_boolean 은 label('true'/'false') 로 판별 (value 는 2/3 이므로 getText 사용)
    let flag = (par_filterList.getText() === 'true');

    target1.setUseFilterList(flag);

    let ignored = (target1.options.headerFilter === true);
    let msg = "setUseFilterList(" + flag + ") 실행"
        + "\n-> options.useFilterList : " + target1.options.useFilterList
        + "\n-> options.headerFilter : " + target1.options.headerFilter
        + (ignored ? "  (headerFilter=true 이므로 useFilterList 설정 무시됨)" : "");
    wf_body_bottom.getObj("scwin").setReturnValue(msg);
}



// [확인] 필터 팝업 유형 : 사용자가 useFilter=true 컬럼의 필터 아이콘을 클릭해 팝업을 연 뒤 실행.
//  useFilterList=true 면 FilterList(.w2grid_customFilter_list, 체크박스 목록), false 면 CustomFilter(.w2grid_customFilter, 입력창).
//  (필터 아이콘 클릭 자체는 사용자 액션 → 별도 트리거 버튼 생성하지 않음)
scwin.btn_checkPopup_onclick = function () {
    let scb = wf_body_bottom.getObj("scwin");

    // 설정된 옵션값
    scb.setReturnValue("[옵션] useFilterList : " + target1.options.useFilterList);

    // 열린 팝업 유형 (FilterList vs CustomFilter)
    let listPopup = document.querySelector(".w2grid_customFilter_list");
    let customPopup = document.querySelector(".w2grid_customFilter");
    let hasList = !!listPopup;
    let hasCustom = !!customPopup;
    if (!hasList && !hasCustom) {
        scb.setReturnValue("열린 필터 팝업이 없습니다. useFilter 컬럼 헤더의 필터 아이콘을 먼저 클릭하세요.");
    } else {
        scb.setReturnValue("FilterList 팝업(.w2grid_customFilter_list) 표시 : " + hasList + " / CustomFilter 팝업(.w2grid_customFilter) 표시 : " + hasCustom);
    }

    // RowNum / RowStatus Header 필터 아이콘 유무
    let rowNumTh = document.querySelector("[id*='_headerRowNumber']");
    let rowStatusTh = document.querySelector("[id*='_headerRowStatus']");
    let rowNumHasFilter = rowNumTh ? !!rowNumTh.querySelector("input.w2grid_customFilter_open") : null;
    let rowStatusHasFilter = rowStatusTh ? !!rowStatusTh.querySelector("input.w2grid_customFilter_open") : null;
    scb.setReturnValue("RowNum Header 필터 아이콘 : " + rowNumHasFilter + " / RowStatus Header 필터 아이콘 : " + rowStatusHasFilter);
}
